/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 2.0
 */
public class Simulator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // The default dimensions
    private static final int DEFAULT_WIDTH = 120;
    private static final int DEFAULT_DEPTH = 80;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    // List of animals in the field.
    private final List<Actor> animals;
    private final List<Actor> plants;
    // The current state of the field.
    private final Field field;

    private final SimulatorClock clock;
    private final WeatherHandler weatherHandler;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private final SimulatorView view;
    // handles the simulation of the disease
    private final DiseaseHandler diseaseHandler;
    // swing component dashboard
    private Dashboard dashboard;
    // generator for the initial terrain and population
    private final PopulationGenerator populationGenerator;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a simulation field with default size.
     */
    public Simulator() throws Exception
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * 
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width) throws Exception
    {
        if(depth % 20 != 0 || width % 20 != 0) {
            throw new Exception("Depth and Width must be factors of 20");
        }

        if(width <= 0 || depth <= 0) {
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        animals = new ArrayList<>();
        plants = new ArrayList<>();
        field = new Field(depth, width);
        clock = new SimulatorClock();
        weatherHandler = new WeatherHandler(clock);
        diseaseHandler = new DiseaseHandler( field);
        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width, this);
        populationGenerator = new PopulationGenerator(view, field);

        reset();
    }

    /**
     * Sets the dashboard field to later updates the interface at the end of simulation steps.
     * 
     * @param newDashboard the dashboard to be updated.
     */
    public void setDashboard(Dashboard newDashboard) {
        this.dashboard = newDashboard;
    }

    /**
     * @return the disease infection history accumulated so far.
     */
    public Map<Integer, Integer> getDiseaseHistory()
    {
        return diseaseHandler.getInfectionHistory();
    }

    /*///////////////////////////////////////////////////////////////
                          ECOSYSTEM SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (1000 steps).
     */
    public void runLongSimulation()
    {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * 
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            //delay(1000);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;
        advanceSimulationState();
        List<Actor> newAnimals = new ArrayList<>();
        List<Actor> newPlants = new ArrayList<>();
        actorsAct(plants, newPlants, weatherHandler.getWeather(), clock.getDayState());
        actorsAct(animals, newAnimals, weatherHandler.getWeather(), clock.getDayState());
        refreshViews();
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        animals.clear();
        plants.clear();
        populationGenerator.populate(animals, plants);

        // Show the starting state in the view.
        view.showStatus(step, field, clock, weatherHandler.getWeather());
    }

    /**
     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
     * 
     * @param actors List of all actors in the field.
     * @param newActors List of newborns after actors act.
     */
    private void actorsAct(List<Actor> actors, List<Actor> newActors, Weather weather, DayState dayState) {
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            actor.act(newActors, weather, dayState);
            if(! actor.isAlive()) {
                it.remove();
            }
        }
        actors.addAll(newActors);
    }

    /**
     * Advance the clock, weather, and disease state for the current step.
     */
    private void advanceSimulationState()
    {
        clock.incrementStep();
        weatherHandler.updateWeather();
        diseaseHandler.simulateDiseaseStep();
    }

    /**
     * Repaint the view and dashboard after a simulation step.
     */
    private void refreshViews()
    {
        view.showStatus(step, field, clock, weatherHandler.getWeather());
        if(dashboard != null) {
            dashboard.updateDashboard();
        }
    }
}

/**
 * Responsible for mutating the weather of the simulation by randomly selecting a new weather(following a uniform distribution)
 * @version 1.0
 */
public class WeatherHandler
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private Weather currentWeather;
    private int lastRecordedDay;
    private final SimulatorClock clock;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new Weather handler
     */
    public WeatherHandler(SimulatorClock clock)
    {
        currentWeather = getRandomWeather();
        lastRecordedDay = 1;
        this.clock = clock;
    }

    /**
     * Accessor Method for the current weathet
     * @return the current weather
     */
    public Weather getWeather()
    {
        return currentWeather;
    }

    /**
     * Randomly selects a new weather everyday
     */
    public void updateWeather()
    {
        if(lastRecordedDay != clock.getDayCount()) {
            currentWeather = getRandomWeather();
            lastRecordedDay = clock.getDayCount();
        }
    }

    /**
     *  Returns a random weather amongs the list of possible types of weather
     *  @return the randomly selected weather
     */
    private Weather getRandomWeather()
    {
        return Utils.getRandomEnumValue(Weather.class);
    }
}

/**
 * Simulates the behaviour of time by synchronizing itself with the current step of the simulation(linear formula: time = k * step)
 *
 * @version 1.0
 */
public class SimulatorClock
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final int INITIAL_TIME = 12;
    private final int TIME_FACTOR = 3;
    private final int STEPS_PER_DAY = 8;
    private int step;
    private int dayCount;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/    

    /**
     * Constructor for objects of class SimulatorClock.
     */
    public SimulatorClock()
    {
        step = 0;
    }

    /**
     * Returns a string indicating the time of the day in a human friendly format.
     * 
     * @return A string of the current time of the day in a Day:Hour:Minute format.
     */

    public String getStringTime()
    {
        String hourString = Utils.padLeft(String.valueOf(getHourOfDay()), 2);
        String minuteString = Utils.padRight(String.valueOf(getMinuteOfDay()), 2);
        return String.format("Day: %s | %s : %s ",getDayCount(),hourString, minuteString);
    }

    /*///////////////////////////////////////////////////////////////
                          TIME SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Acessor method for the current time(starts at mid day).
     * 
     * @return the current time.
     */
    public double getTime()
    {
        return (((double)(TIME_FACTOR) * step) + INITIAL_TIME) % 24;
    }

    /**
     * Accessor method for the current hour of the day.
     * 
     * @return the current hour (floored).
     */
    public int getHourOfDay()
    {
        return (int) getTime();
    }

    /**
     * The remainder of the current hours.
     * 
     * @return the minutes passed since the start of the last hour.
     */
    public int getMinuteOfDay()
    {
        return (int)((getTime() - (double)getHourOfDay()) * 100.0 * 0.6);
    }

    /**
     * Increments the internal steps of the clock.
     */
    public void incrementStep()
    {
        step++;
    }

    /**
     * Returns the number of days passed since the start of the simulation(starts at day 1).
     * 
     * @return the current day of the simulation.
     */
    public int getDayCount()
    {
        return ((int)((step + (INITIAL_TIME/TIME_FACTOR)) / STEPS_PER_DAY) + 1);
    }

    /**
     * Returns the current state of the day.
     * 
     * @returns the state of the day.
     */
    public DayState getDayState()
    {
        if(getTime() > 24 || getTime() < 6) {
            return DayState.NIGHT;
        } else {
            return DayState.DAYLIGHT;
        }
    }
}

