 11	public class FieldStats
 12	{
 13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
 14	    private final Map<Class<?>, Counter> counters;
 15	    // Whether the counters are currently up to date.
 16	    private boolean countsValid;
 17	
 18	    /**
 19	     * Construct a FieldStats object.
 20	     */
 21	    public FieldStats()
 22	    {
 23	        // Set up a collection for counters for each type of animal that
 24	        // we might find
 25	        counters = new LinkedHashMap<>();
 26	        countsValid = true;
 27	    }
 28	
 29	    /**
 30	     * Get details of what is in the field.
 31	     * @return A string describing what is in the field.
 32	     */
 33	    public String getPopulationDetails(Field field)
 34	    {
 35	        StringBuffer buffer = new StringBuffer();
 36	        if(!countsValid) {
 37	            generateCounts(field);
 38	        }
 39	        for(Class<?> key : counters.keySet()) {
 40	            Counter info = counters.get(key);
 41	            buffer.append(info.getName());
 42	            buffer.append(": ");
 43	            buffer.append(info.getCount());
 44	            buffer.append(" ");
 45	        }
 46	        return buffer.toString();
 47	    }
 48	    
 49	    /**
 50	     * Invalidate the current set of statistics; reset all 
 51	     * counts to zero.
 52	     */
 53	    public void reset()
 54	    {
 55	        countsValid = false;
 56	        for(Class<?> key : counters.keySet()) {
 57	            Counter count = counters.get(key);
 58	            count.reset();
 59	        }
 60	    }
 61	
 62	    /**
 63	     * Increment the count for one class of animal.
 64	     * @param animalClass The class of animal to increment.
 65	     */
 66	    public void incrementCount(Class<?> animalClass)
 67	    {
 68	        Counter count = counters.get(animalClass);
 69	        if(count == null) {
 70	            // We do not have a counter for this species yet.
 71	            // Create one.
 72	            count = new Counter(getDisplayName(animalClass));
 73	            counters.put(animalClass, count);
 74	        }
 75	        count.increment();
 76	    }
 77	
 78	    /**
 79	     * Indicate that an animal count has been completed.
 80	     */
 81	    public void countFinished()
 82	    {
 83	        countsValid = true;
 84	    }
 85	
 86	    /**
 87	     * Determine whether the simulation is still viable.
 88	     * I.e., should it continue to run.
 89	     * @return true If there is more than one species alive.
 90	     */
 91	    public boolean isViable(Field field)
 92	    {
 93	        // How many counts are non-zero.
 94	        int nonZero = 0;
 95	        if(!countsValid) {
 96	            generateCounts(field);
 97	        }
 98	        for(Class<?> key : counters.keySet()) {
 99	            Counter info = counters.get(key);
100	            if(info.getCount() > 0) {
101	                nonZero++;
102	            }
103	        }
104	        return nonZero > 1;
105	    }
106	    
107	    /**
108	     * Generate counts of the number of foxes and rabbits.
109	     * These are not kept up to date as foxes and rabbits
110	     * are placed in the field, but only when a request
111	     * is made for the information.
112	     * @param field The field to generate the stats for.
113	     */
114	    private void generateCounts(Field field)
115	    {
116	        reset();
117	        for(int row = 0; row < field.getDepth(); row++) {
118	            for(int col = 0; col < field.getWidth(); col++) {
119	                Animal animal = field.getAnimalAt(row, col);
120	                Plant plant = field.getPlantAt(row, col);
121	                if(animal != null) {
122	                    incrementCount(animal.getClass());
123	                }
124	                if(plant != null) {
125	                    incrementCount(plant.getClass());
126	                }
127	            }
128	        }
129	        countsValid = true;
130	    }
131	    public Map<Class<?>, Counter> getCounters()
132	    {
133	        return counters;
134	    }
135	
136	    /**
137	     * Resolve the user-facing display name for a class tracked in the simulation.
138	     *
139	     * @param actorClass the tracked class.
140	     * @return a readable name for the class.
141	     */
142	    private String getDisplayName(Class<?> actorClass)
143	    {
144	        AnimalType animalType = AnimalType.fromActorClass(actorClass);
145	        if(animalType != null) {
146	            return animalType.getDisplayName();
147	        }
148	
149	        PlantType plantType = PlantType.fromActorClass(actorClass);
150	        if(plantType != null) {
151	            return plantType.getDisplayName();
152	        }
153	
154	        return actorClass.getSimpleName();
155	    }
156	}

 1	/**
 2	 * Responsible for mutating the weather of the simulation by randomly selecting a new weather(following a uniform distribution)
 3	 * @version 1.0
 4	 */
 5	public class WeatherHandler
 6	{
 7	    
 8	    /*///////////////////////////////////////////////////////////////
 9	                                   STATE
10	    //////////////////////////////////////////////////////////////*/
11	    
12	    private Weather currentWeather;
13	    private int lastRecordedDay;
14	    private final SimulatorClock clock;
15	    
16	    /*///////////////////////////////////////////////////////////////
17	                                CONSTRUCTOR
18	    //////////////////////////////////////////////////////////////*/
19	    
20	    /**
21	     * Creates a new Weather handler
22	     */
23	    public WeatherHandler(SimulatorClock clock)
24	    {
25	        currentWeather = getRandomWeather();
26	        lastRecordedDay = 1;
27	        this.clock = clock;
28	    }
29	    
30	    /**
31	     * Accessor Method for the current weathet
32	     * @return the current weather
33	     */
34	    public Weather getWeather()
35	    {
36	        return currentWeather;
37	    }
38	    
39	    /**
40	     * Randomly selects a new weather everyday
41	     */
42	    public void updateWeather()
43	    {
44	        if(lastRecordedDay != clock.getDayCount()) {
45	            currentWeather = getRandomWeather();
46	            lastRecordedDay = clock.getDayCount();
47	        }
48	    }
49	    
50	    /**
51	     *  Returns a random weather amongs the list of possible types of weather
52	     *  @return the randomly selected weather
53	     */
54	    private Weather getRandomWeather()
55	    {
56	        return Utils.getRandomEnumValue(Weather.class);
57	    }
58	}

  1	import java.util.List;
  2	import java.util.ArrayList;
  3	import java.util.Iterator;
  4	import java.util.Map;
  5	/**
  6	 * A simple predator-prey simulator, based on a rectangular field
  7	 * containing rabbits and foxes.
  8	 *
  9	 * @version 2.0
 10	 */
 11	public class Simulator
 12	{
 13	    
 14	    /*///////////////////////////////////////////////////////////////
 15	                                 CONSTANTS
 16	    //////////////////////////////////////////////////////////////*/
 17	    
 18	    // The default dimensions
 19	    private static final int DEFAULT_WIDTH = 120;
 20	    private static final int DEFAULT_DEPTH = 80;
 21	    
 22	    /*///////////////////////////////////////////////////////////////
 23	                                   STATE
 24	    //////////////////////////////////////////////////////////////*/
 25	    
 26	    // List of animals in the field.
 27	    private final List<Actor> animals;
 28	    private final List<Actor> plants;
 29	    // The current state of the field.
 30	    private final Field field;
 31	    
 32	    private final SimulatorClock clock;
 33	    private final WeatherHandler weatherHandler;
 34	    // The current step of the simulation.
 35	    private int step;
 36	    // A graphical view of the simulation.
 37	    private final SimulatorView view;
 38	    // handles the simulation of the disease
 39	    private final DiseaseHandler diseaseHandler;
 40	    // swing component dashboard
 41	    private Dashboard dashboard;
 42	    // generator for the initial terrain and population
 43	    private final PopulationGenerator populationGenerator;
 44	    
 45	    /*///////////////////////////////////////////////////////////////
 46	                                CONSTRUCTORS
 47	    //////////////////////////////////////////////////////////////*/
 48	    
 49	    /**
 50	     * Construct a simulation field with default size.
 51	     */
 52	    public Simulator() throws Exception
 53	    {
 54	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 55	    }
 56	    
 57	    /**
 58	     * Create a simulation field with the given size.
 59	     * 
 60	     * @param depth Depth of the field. Must be greater than zero.
 61	     * @param width Width of the field. Must be greater than zero.
 62	     */
 63	    public Simulator(int depth, int width) throws Exception
 64	    {
 65	        if(depth % 20 != 0 || width % 20 != 0) {
 66	            throw new Exception("Depth and Width must be factors of 20");
 67	        }
 68	        
 69	        if(width <= 0 || depth <= 0) {
 70	            depth = DEFAULT_DEPTH;
 71	            width = DEFAULT_WIDTH;
 72	        }
 73	        
 74	        animals = new ArrayList<>();
 75	        plants = new ArrayList<>();
 76	        field = new Field(depth, width);
 77	        clock = new SimulatorClock();
 78	        weatherHandler = new WeatherHandler(clock);
 79	        diseaseHandler = new DiseaseHandler( field);
 80	        // Create a view of the state of each location in the field.
 81	        view = new SimulatorView(depth, width, this);
 82	        populationGenerator = new PopulationGenerator(view, field);
 83	        
 84	        reset();
 85	    }
 86	    
 87	    /**
 88	     * Sets the dashboard field to later updates the interface at the end of simulation steps.
 89	     * 
 90	     * @param newDashboard the dashboard to be updated.
 91	     */
 92	    public void setDashboard(Dashboard newDashboard) {
 93	        this.dashboard = newDashboard;
 94	    }
 95	
 96	    /**
 97	     * @return the disease infection history accumulated so far.
 98	     */
 99	    public Map<Integer, Integer> getDiseaseHistory()
100	    {
101	        return diseaseHandler.getInfectionHistory();
102	    }
103	    
104	    /*///////////////////////////////////////////////////////////////
105	                          ECOSYSTEM SIMULATION LOGIC
106	    //////////////////////////////////////////////////////////////*/
107	    
108	    /**
109	     * Run the simulation from its current state for a reasonably long period,
110	     * (1000 steps).
111	     */
112	    public void runLongSimulation()
113	    {
114	        simulate(1000);
115	    }
116	    
117	    /**
118	     * Run the simulation from its current state for the given number of steps.
119	     * Stop before the given number of steps if it ceases to be viable.
120	     * 
121	     * @param numSteps The number of steps to run for.
122	     */
123	    public void simulate(int numSteps)
124	    {
125	        for(int remainingSteps = numSteps; remainingSteps > 0 && view.isViable(field); remainingSteps--) {
126	            simulateOneStep();
127	            //delay(1000);   // uncomment this to run more slowly
128	        }
129	    }
130	    
131	    /**
132	     * Run the simulation from its current state for a single step.
133	     * Iterate over the whole field updating the state of each
134	     * fox and rabbit.
135	     */
136	    public void simulateOneStep()
137	    {
138	        step++;
139	        advanceSimulationState();
140	        Weather weather = weatherHandler.getWeather();
141	        DayState dayState = clock.getDayState();
142	        advanceActorGroup(plants, weather, dayState);
143	        advanceActorGroup(animals, weather, dayState);
144	        refreshViews();
145	    }
146	        
147	    /**
148	     * Reset the simulation to a starting position.
149	     */
150	    public void reset()
151	    {
152	        step = 0;
153	        animals.clear();
154	        plants.clear();
155	        populationGenerator.populate(animals, plants);
156	        
157	        // Show the starting state in the view.
158	        view.showStatus(step, field, clock, weatherHandler.getWeather());
159	    }
160	    
161	    /**
162	     * Iterates through a set of actors and makes them act, then removes the dead and appends newborns.
163	     *
164	     * @param actors List of all actors in the field.
165	     * @param weather current weather state.
166	     * @param dayState current day state.
167	     */
168	    private void advanceActorGroup(List<Actor> actors, Weather weather, DayState dayState)
169	    {
170	        List<Actor> newActors = new ArrayList<>();
171	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
172	            Actor actor = it.next();
173	            actor.act(newActors, weather, dayState);
174	            if(! actor.isAlive()) {
175	                it.remove();
176	            }
177	        }
178	        actors.addAll(newActors);
179	    }
180	
181	    /**
182	     * Advance the clock, weather, and disease state for the current step.
183	     */
184	    private void advanceSimulationState()
185	    {
186	        clock.incrementStep();
187	        weatherHandler.updateWeather();
188	        diseaseHandler.simulateDiseaseStep();
189	    }
190	
191	    /**
192	     * Repaint the view and dashboard after a simulation step.
193	     */
194	    private void refreshViews()
195	    {
196	        view.showStatus(step, field, clock, weatherHandler.getWeather());
197	        if(dashboard != null) {
198	            dashboard.updateDashboard();
199	        }
200	    }
201	}
